import { Job } from "./Job";
/**
 * @class
 * @memberOf next2d.ui
 */
export class Tween {
    /**
     * @description 新しいJobクラスを追加します
     *              Add a new Job class
     *
     * @param  {object}   target
     * @param  {object}   from
     * @param  {object}   to
     * @param  {number}   [delay=0]
     * @param  {number}   [duration=1]
     * @param  {function} [ease=null]
     * @return {Job}
     * @method
     * @static
     */
    static add(target, from, to, delay = 0, duration = 1, ease = null) {
        return new Job(target, from, to, delay, duration, ease);
    }
}
